create table public.stock_takes(id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,branch_id bigint references public.branches(id) on delete set null,audit_number text not null,audit_type text not null default 'manual',status text not null default 'draft',audit_date date not null default current_date,completed_at timestamptz,notes text,metadata jsonb,created_by uuid references public.app_users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(business_id,audit_number));
create table public.stock_take_items(id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,stock_take_id bigint not null references public.stock_takes(id) on delete cascade,product_id bigint not null references public.products(id),stock_id bigint references public.stocks(id) on delete set null,system_quantity integer not null default 0,counted_quantity integer not null default 0,variance integer generated always as (counted_quantity-system_quantity) stored,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.stock_take_items enable row level security; alter table public.stock_takes enable row level security;
revoke all on public.stock_take_items,public.stock_takes from anon,authenticated; grant select,insert,update,delete on public.stock_take_items,public.stock_takes to authenticated;
create policy stock_takes_tenant on public.stock_takes for all to authenticated using(business_id=(select private.current_business_id())) with check(business_id=(select private.current_business_id()));
create policy stock_take_items_tenant on public.stock_take_items for all to authenticated using(business_id=(select private.current_business_id())) with check(business_id=(select private.current_business_id()));
create or replace function private.enforce_stock_take_item_business() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$begin if not exists(select 1 from stock_takes t where t.id=new.stock_take_id and t.business_id=new.business_id) then raise exception 'stock take does not belong to business'; end if; if not exists(select 1 from products p where p.id=new.product_id and p.business_id=new.business_id) then raise exception 'product does not belong to business'; end if; if new.stock_id is not null and not exists(select 1 from stocks s where s.id=new.stock_id and s.business_id=new.business_id and s.product_id=new.product_id) then raise exception 'stock does not belong to business/product'; end if; return new; end$$;
revoke all on function private.enforce_stock_take_item_business() from public,anon,authenticated;
create trigger trg_stock_take_item_business before insert or update on public.stock_take_items for each row execute function private.enforce_stock_take_item_business();